def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 35.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    rich_opp = max(opp_budgets) if opp_budgets else 0.0

    units = supply / WATER_REQ
    very_tight = units < 1.35
    tight = units < 1.6
    ample = units > 1.8

    danger = hp <= 2 or no_water_days >= 2
    caution = hp <= 4 or no_water_days >= 1

    if danger:
        bid = max(62.0, highest_prev + 3.0)
        if very_tight:
            bid = max(bid, 78.0)
        return float(min(budget, bid))

    if very_tight:
        if highest_prev >= 80:
            bid = 81.5 if hp > 4 else 88.0
        elif highest_prev >= 60:
            bid = highest_prev + 2.2
        else:
            bid = 63.0
        return float(min(budget, bid))

    if tight:
        if caution:
            bid = max(58.0, highest_prev + 1.5)
        else:
            if avg_prev >= 65:
                bid = 46.0
            else:
                bid = max(41.0, highest_prev * 0.78)
        return float(min(budget, bid))

    if ample:
        if caution:
            bid = max(34.0, highest_prev * 0.55)
        else:
            bid = 22.0
            if rich_opp > budget * 1.5 and highest_prev < 50:
                bid = 18.0
        return float(min(budget, bid))

    bid = 30.0 if hp > 4 else 48.0
    if highest_prev > 0:
        bid = max(bid, min(highest_prev + 1.0, 60.0))
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    # If no one is alive, conserve
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate yesterday pressure
    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        s = sorted(prev_bids, reverse=True)
        second_prev = float(s[1])

    # Supply tiering: with supply 15-25 and WATER_REQ=9, typically 1 unit often matters.
    # We bias bids based on how likely the top bidder secured water yesterday.
    # If supply is lower, competition for the 1 unit increases.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid level
    # If yesterday highest bid was high, expect continued competition.
    if highest_prev >= DAILY_SALARY * 0.8:
        # High pressure environment
        if my_status['hp'] > 3:
            base = DAILY_SALARY * (0.25 + 0.15 * (1.0 - supply_ratio))
        else:
            base = DAILY_SALARY * (0.75 + 0.15 * (1.0 - supply_ratio))
    else:
        # Moderate pressure
        if my_status['hp'] > 3:
            base = max(DAILY_SALARY * 0.45, highest_prev * 0.95)
        else:
            base = max(DAILY_SALARY * 0.75, highest_prev * 1.05)

    # If there is a strong second bidder, slightly overtake their level to secure allocation.
    # (We don't know today's bids, so we use yesterday's gap as a proxy.)
    if second_prev > 0.0:
        target = second_prev + 2.0
        # Blend target with base to avoid overspending.
        base = 0.6 * base + 0.4 * target

    # If we are already in no-water streak, escalate
    no_water_days = int(my_status.get('no_water_days', 0) or 0)
    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.85)
    elif no_water_days == 1:
        base = max(base, DAILY_SALARY * 0.65)

    # Budget safety cap
    budget = float(my_status['budget'])
    bid = float(min(budget, base))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

